import { createHash } from "node:crypto";
import { cpSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { InMemoryTransport } from "@modelcontextprotocol/sdk/inMemory.js";
import { SnapshotStore, loadEdition } from "../src/snapshot.mjs";
import { createMcpServer } from "../src/server.mjs";

// The public-data tree generated by Hypenomia's exporter. Synthetic: tests opt in.
export const EDITION_DIR = fileURLToPath(new URL("./fixtures/edition-from-export/", import.meta.url));
export const EDITION = "2026-10-26";
export const SYNTH = { allowSynthetic: true };

export async function readyStore(source = EDITION_DIR, opts = {}) {
  const store = new SnapshotStore(source, { ...SYNTH, ...opts });
  await store.refresh();
  return store;
}

export async function connectInMemory(store, opts) {
  const server = createMcpServer(store, opts);
  const [ct, st] = InMemoryTransport.createLinkedPair();
  await server.connect(st);
  const client = new Client({ name: "test", version: "0" });
  await client.connect(ct);
  return { client, close: () => client.close() };
}

export async function call(client, name, args) {
  return client.callTool({ name, arguments: args });
}

export const bytes = (r) => JSON.stringify({ c: r.content, s: r.structuredContent, e: r.isError ?? false });

export function collectKeys(node, set = new Set()) {
  if (Array.isArray(node)) node.forEach((v) => collectKeys(v, set));
  else if (node && typeof node === "object") for (const [k, v] of Object.entries(node)) { set.add(k); collectKeys(v, set); }
  return set;
}

export function copyEdition() {
  const dir = mkdtempSync(path.join(tmpdir(), "edition-"));
  cpSync(EDITION_DIR, dir, { recursive: true });
  return dir;
}

const sha = (buf) => createHash("sha256").update(buf).digest("hex");
const editionFile = (dir, name) => path.join(dir, "editions", EDITION, `${name}.json`);

// Edits one JSON file of a copied edition and keeps the manifest and latest.json hashes consistent.
export function rewrite(dir, name, fn) {
  if (name === "manifest") {
    const m = JSON.parse(readFileSync(editionFile(dir, "manifest"), "utf8"));
    fn(m);
    return writeManifest(dir, m);
  }
  const p = editionFile(dir, name);
  const body = JSON.parse(readFileSync(p, "utf8"));
  fn(body);
  const buf = Buffer.from(JSON.stringify(body, null, 2) + "\n");
  writeFileSync(p, buf);
  const m = JSON.parse(readFileSync(editionFile(dir, "manifest"), "utf8"));
  const e = m.files.find((f) => f.name === name);
  e.sha256 = sha(buf);
  e.bytes = buf.length;
  writeManifest(dir, m);
}

function writeManifest(dir, m) {
  const buf = Buffer.from(JSON.stringify(m, null, 2) + "\n");
  writeFileSync(editionFile(dir, "manifest"), buf);
  rewriteLatest(dir, (l) => { l.retained.find((r) => r.edition === l.edition).manifest_sha256 = sha(buf); });
}

export function rewriteLatest(dir, fn) {
  const p = path.join(dir, "latest.json");
  const l = JSON.parse(readFileSync(p, "utf8"));
  fn(l);
  writeFileSync(p, JSON.stringify(l, null, 2) + "\n");
}

export { loadEdition };
